import pc from 'picocolors'
import { VERSION, CLI_NAME } from './constants.js'

// ASCII art generated by: npx figlet-cli -f "ANSI Shadow" "gsc"
const ART = `
 ██████╗ ███████╗ ██████╗
██╔════╝ ██╔════╝██╔════╝
██║  ███╗███████╗██║
██║   ██║╚════██║██║
╚██████╔╝███████║╚██████╗
 ╚═════╝ ╚══════╝ ╚═════╝
`.trimStart()

export function banner(profile?: string): string {
  const colored = ART.split('\n').map(line => pc.bold(line)).join('\n')
  const info = pc.dim(`${CLI_NAME} v${VERSION}`) + (profile ? pc.dim(` — ${profile}`) : '')
  return `${colored}${info}\n`
}
